import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AnimatedReceiptProps = Record<string, any>;

const AnimatedReceipt: React.FC<AnimatedReceiptProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 2,
  receiptColor = "#ffffff",
  lineColor = "#e5e7eb",
  textColor = "#374151",
  totalColor = "#f97316",
  totalAmount = 847,
  currency = "$",
  lineItems = ["Monthly Fee", "Per-Call Charge", "Overage Fees"],
  title = "INVOICE"
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Math
  const receiptWidth = width * 0.35;
  const padding = width * 0.035;
  const fontSizeItem = width * 0.015;
  const fontSizeTotal = width * 0.025;
  const fontSizeTitle = width * 0.012;

  // Deterministic amounts for line items summing up to totalAmount
  const itemAmounts = React.useMemo(() => {
    if (lineItems.length === 0) return [];
    let remaining = totalAmount;
    return lineItems.map((_, i) => {
      if (i === lineItems.length - 1) return remaining;
      const amt = Math.floor(totalAmount * (0.8 / lineItems.length));
      remaining -= amt;
      return amt;
    });
  }, [lineItems, totalAmount]);

  // Timing constants
  const itemsStartFrame = 10;
  const itemStagger = 5;
  const counterEndFrame = itemsStartFrame + (lineItems.length * itemStagger) + 10;
  
  // Exit starts 20 frames before the end of the duration
  const totalFrames = durationInSeconds * fps;
  const exitStartFrame = totalFrames - 20;

  // Animations
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 }
  });

  const exitProgress = spring({
    frame: Math.max(0, frame - exitStartFrame),
    fps,
    config: { damping: 14, mass: 0.8 }
  });

  // Receipt global position and opacity
  const entryY = interpolate(entranceProgress, [0, 1], [height * 0.8, 0]);
  const exitY = interpolate(exitProgress, [0, 1], [0, -height * 0.3]);
  const currentY = entryY + exitY;
  
  const receiptOpacity = interpolate(exitProgress, [0, 1], [1, 0]);

  // Running Total logic
  const currentTotal = interpolate(
    frame,
    [itemsStartFrame, counterEndFrame],
    [0, totalAmount],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic)
    }
  );

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Inter, sans-serif",
        justifyContent: "center",
        alignItems: "center",
        transition: "none"
      }}
    >
      <div
        style={{
          width: receiptWidth,
          backgroundColor: receiptColor,
          borderRadius: 24,
          padding: padding,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.15), 0 0 1px rgba(0,0,0,0.1)",
          transform: `translateY(${currentY}px)`,
          opacity: receiptOpacity,
          display: "flex",
          flexDirection: "column",
          transition: "none"
        }}
      >
        {/* Header */}
        <div
          style={{
            fontSize: fontSizeTitle,
            fontWeight: 700,
            color: textColor,
            letterSpacing: 4,
            marginBottom: padding * 0.8,
            textAlign: "center",
            opacity: 0.6,
            transition: "none"
          }}
        >
          {title.toUpperCase()}
        </div>

        {/* Line Items */}
        <div style={{ display: "flex", flexDirection: "column", transition: "none" }}>
          {lineItems.map((item, i) => {
            const itemFrame = Math.max(0, frame - itemsStartFrame - (i * itemStagger));
            const itemProgress = spring({
              frame: itemFrame,
              fps,
              config: { damping: 12, mass: 0.5 }
            });

            const itemOpacity = itemProgress;
            const itemY = interpolate(itemProgress, [0, 1], [20, 0]);

            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: `${padding * 0.4}px 0`,
                  borderBottom: `2px solid ${lineColor}`,
                  opacity: itemOpacity,
                  transform: `translateY(${itemY}px)`,
                  color: textColor,
                  fontSize: fontSizeItem,
                  fontWeight: 500,
                  transition: "none"
                }}
              >
                <span>{item}</span>
                <span style={{ fontWeight: 600 }}>
                  {currency}{itemAmounts[i].toLocaleString("en-US")}
                </span>
              </div>
            );
          })}
        </div>

        {/* Total Footer */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            paddingTop: padding * 0.8,
            fontSize: fontSizeTotal,
            fontWeight: 800,
            color: totalColor,
            transition: "none"
          }}
        >
          <span>TOTAL</span>
          <span>
            {currency}{Math.floor(currentTotal).toLocaleString("en-US")}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AnimatedReceipt;